begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
delete from public.team_members;
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000000901','edit.design@example.test'),('00000000-0000-4000-8000-000000000902','edit.operator@example.test'),('00000000-0000-4000-8000-000000000903','edit.finance@example.test');
insert into public.team_members(id,auth_user_id,email,display_name) values('00000000-0000-4000-8000-000000000911','00000000-0000-4000-8000-000000000901','edit.design@example.test','Diseño'),('00000000-0000-4000-8000-000000000912','00000000-0000-4000-8000-000000000902','edit.operator@example.test','Taller'),('00000000-0000-4000-8000-000000000913','00000000-0000-4000-8000-000000000903','edit.finance@example.test','Finanzas');
insert into public.team_member_roles(member_id,role) values('00000000-0000-4000-8000-000000000911','designer'),('00000000-0000-4000-8000-000000000912','operator'),('00000000-0000-4000-8000-000000000913','finance');
set local role authenticated;
set local "request.jwt.claim.sub"='00000000-0000-4000-8000-000000000901';
select public.save_customer('00000000-0000-4000-8000-000000000921',null,'{"display_name":"Cliente edición"}');
select public.create_direct_order('00000000-0000-4000-8000-000000000922','00000000-0000-4000-8000-000000000921',null,null,'','[{"description":"Imanes","client_description":"Imanes de animales","specifications":"Cortar","quantity":100,"amount":"100"},{"description":"Folletos","client_description":"Folletos color","specifications":"","quantity":200,"amount":"200"}]');
select public.create_direct_order('00000000-0000-4000-8000-000000000923','00000000-0000-4000-8000-000000000921',null,null,'','[{"description":"Imanes","client_description":"Imanes de animales","specifications":"Cortar","quantity":100,"amount":"100"},{"description":"Folletos","client_description":"Folletos color","specifications":"","quantity":200,"amount":"200"}]');
select public.create_direct_order('00000000-0000-4000-8000-000000000924','00000000-0000-4000-8000-000000000921',null,null,'','[{"description":"Imanes","client_description":"Imanes de animales","specifications":"Cortar","quantity":100,"amount":"100"},{"description":"Folletos","client_description":"Folletos color","specifications":"","quantity":200,"amount":"200"}]');
select public.create_direct_order('00000000-0000-4000-8000-000000000925','00000000-0000-4000-8000-000000000921',null,null,'','[{"description":"Imanes","client_description":"Imanes de animales","specifications":"Cortar","quantity":100,"amount":"100"},{"description":"Folletos","client_description":"Folletos color","specifications":"","quantity":200,"amount":"200"}]');
select public.create_direct_order('00000000-0000-4000-8000-000000000926','00000000-0000-4000-8000-000000000921',null,null,'','[{"description":"Imanes","client_description":"Imanes de animales","specifications":"Cortar","quantity":100,"amount":"100"},{"description":"Folletos","client_description":"Folletos color","specifications":"","quantity":200,"amount":"200"}]');
select public.create_direct_order('00000000-0000-4000-8000-000000000927','00000000-0000-4000-8000-000000000921',null,null,'','[{"description":"Imanes","client_description":"Imanes de animales","specifications":"Cortar","quantity":100,"amount":"100"},{"description":"Folletos","client_description":"Folletos color","specifications":"","quantity":200,"amount":"200"}]');
select public.assign_production('00000000-0000-4000-8000-000000000922','00000000-0000-4000-8000-000000000912',1,'Primera asignación');
select lives_ok($$select public.edit_order('00000000-0000-4000-8000-000000000922',1,(select jsonb_agg(jsonb_build_object('id',id,'description',description,'client_description',client_description,'specifications',specifications,'quantity',quantity,'amount',amount) order by position) from public.order_items where order_id='00000000-0000-4000-8000-000000000922'),'Trabajo editado','{}','Notas nuevas')$$,'Edita nota pendiente sin cobros');
select is((select total from public.orders where id='00000000-0000-4000-8000-000000000922'),300::numeric,'Total coincide con suma de ítems');
select is((select production_revision from public.orders where id='00000000-0000-4000-8000-000000000922'),2,'Aumenta revisión compartida con ficha');
select is((select assigned_to from public.orders where id='00000000-0000-4000-8000-000000000922'),'00000000-0000-4000-8000-000000000912'::uuid,'Conserva responsable');
select is((select work_description from public.orders where id='00000000-0000-4000-8000-000000000922'),'Trabajo editado','Guarda encabezado');
select throws_ok($$select public.edit_order('00000000-0000-4000-8000-000000000922',1,(select jsonb_agg(jsonb_build_object('id',id,'description',description,'client_description',client_description,'specifications',specifications,'quantity',quantity,'amount',amount) order by position) from public.order_items where order_id='00000000-0000-4000-8000-000000000922'),'Trabajo editado','{}','Notas nuevas')$$,'40001',null,'Formulario viejo no pisa cambios');
select throws_ok($$select public.delete_order('00000000-0000-4000-8000-000000000922',1,(select number from public.orders where id='00000000-0000-4000-8000-000000000922'))$$,'40001',null,'Borrado viejo no elimina cambios');
select throws_ok($$select public.edit_order('00000000-0000-4000-8000-000000000922',2,'[]','Trabajo editado','{}','Notas nuevas')$$,'22023',null,'No puede quitar todos los ítems');
select throws_ok($$select public.edit_order('00000000-0000-4000-8000-000000000922',2,(select jsonb_agg(jsonb_build_object('id',id,'description',description,'client_description',client_description,'specifications',specifications,'quantity',quantity,'amount',amount) order by position) from public.order_items where order_id='00000000-0000-4000-8000-000000000923'),'Trabajo editado','{}','Notas nuevas')$$,'22023',null,'No acepta ítems de otra nota');
select throws_ok($$select public.edit_order('00000000-0000-4000-8000-000000000922',2,(select jsonb_build_array(to_jsonb(i),to_jsonb(i)) from public.order_items i where order_id='00000000-0000-4000-8000-000000000922' limit 1),'Trabajo editado','{}','Notas nuevas')$$,'22023',null,'No acepta IDs repetidos');
select throws_ok($$select public.edit_order('00000000-0000-4000-8000-000000000922',2,'[{"description":"Mal","client_description":"Mal","specifications":"","quantity":0,"amount":"5"}]','Trabajo editado','{}','Notas nuevas')$$,'22023',null,'Cantidad inválida no persiste');
select throws_ok($$select public.edit_order('00000000-0000-4000-8000-000000000922',2,'[{"description":"Mal","client_description":"Mal","specifications":"","quantity":1,"amount":"0.001"}]','Trabajo editado','{}','Notas nuevas')$$,'22023',null,'No redondea importes inválidos');
select lives_ok($$select public.edit_order('00000000-0000-4000-8000-000000000922',2,(select jsonb_build_array(jsonb_build_object('id',id,'description','Imanes nuevos','client_description','Imanes nuevos','specifications','','quantity',500,'amount','150.50'),'{"description":"Adhesivos","client_description":"Adhesivos color","specifications":"","quantity":10,"amount":"70"}'::jsonb) from public.order_items where order_id='00000000-0000-4000-8000-000000000922' and position=2),'Trabajo editado','{}','Notas nuevas')$$,'Quita primero, conserva segundo y agrega nuevo ítem');
select is((select count(*) from public.order_items where order_id='00000000-0000-4000-8000-000000000922'),2::bigint,'Guarda solamente los ítems elegidos');
select is((select total from public.orders where id='00000000-0000-4000-8000-000000000922'),220.50::numeric,'Recalcula total exacto');
select is((public.order_money('00000000-0000-4000-8000-000000000922')->>'balance')::numeric,220.50::numeric,'Saldo refleja edición');
select is((select quantity from public.order_items where order_id='00000000-0000-4000-8000-000000000922' and position=1),500,'Actualiza cantidad y posición');
select is((select count(*) from public.order_items where order_id='00000000-0000-4000-8000-000000000922' and production_status='pending'),2::bigint,'Todos siguen pendientes');
select throws_ok($$select public.delete_order('00000000-0000-4000-8000-000000000922',3,-1)$$,'22023',null,'Exige número correcto al borrar');
-- Un cobro registrado después de abrir el editor impide ambas operaciones.
set local "request.jwt.claim.sub"='00000000-0000-4000-8000-000000000903';
select public.record_payment('00000000-0000-4000-8000-000000000950','00000000-0000-4000-8000-000000000923',10,'1901-01-15','cash','Cobro');
select throws_ok($$select public.edit_order('00000000-0000-4000-8000-000000000922',3,(select jsonb_agg(jsonb_build_object('id',id,'description',description,'client_description',client_description,'specifications',specifications,'quantity',quantity,'amount',amount) order by position) from public.order_items where order_id='00000000-0000-4000-8000-000000000922'),'Trabajo editado','{}','Notas nuevas')$$,'42501',null,'Finanzas no modifica ítems');
select throws_ok($$select public.delete_order('00000000-0000-4000-8000-000000000922',3,1)$$,'42501',null,'Finanzas no borra notas');
set local "request.jwt.claim.sub"='00000000-0000-4000-8000-000000000901';
select throws_ok($$select public.edit_order('00000000-0000-4000-8000-000000000923',1,(select jsonb_agg(jsonb_build_object('id',id,'description',description,'client_description',client_description,'specifications',specifications,'quantity',quantity,'amount',amount) order by position) from public.order_items where order_id='00000000-0000-4000-8000-000000000923'),'Trabajo editado','{}','Notas nuevas')$$,'23514',null,'Bloquea edición con pago parcial');
select throws_ok($$select public.delete_order('00000000-0000-4000-8000-000000000923',1,(select number from public.orders where id='00000000-0000-4000-8000-000000000923'))$$,'23514',null,'Bloquea borrado con pago parcial');
select throws_ok($$select public.save_order_work_details('00000000-0000-4000-8000-000000000923',1,(select jsonb_agg(jsonb_build_object('id',id,'description',description,'client_description',client_description,'specifications',specifications,'quantity',quantity,'amount',amount) order by position) from public.order_items where order_id='00000000-0000-4000-8000-000000000923'),'Cambio','{}')$$,'23514',null,'Editor anterior no permite evadir bloqueo por cobro');
select is((public.order_money('00000000-0000-4000-8000-000000000923')->>'paid')::numeric,10::numeric,'Conserva ingreso real');
select public.create_direct_order('00000000-0000-4000-8000-000000000928','00000000-0000-4000-8000-000000000921',null,null,'','[{"description":"Imanes","client_description":"Imanes de animales","specifications":"Cortar","quantity":100,"amount":"100"},{"description":"Folletos","client_description":"Folletos color","specifications":"","quantity":200,"amount":"200"}]','{"amount":"1","paid_on":"1901-01-15","method":"cash"}');
select throws_ok($$select public.edit_order('00000000-0000-4000-8000-000000000928',1,(select jsonb_agg(jsonb_build_object('id',id,'description',description,'client_description',client_description,'specifications',specifications,'quantity',quantity,'amount',amount) order by position) from public.order_items where order_id='00000000-0000-4000-8000-000000000928'),'Trabajo editado','{}','Notas nuevas')$$,'23514',null,'Una seña mínima también bloquea edición');
select throws_ok($$select public.delete_order('00000000-0000-4000-8000-000000000928',1,(select number from public.orders where id='00000000-0000-4000-8000-000000000928'))$$,'23514',null,'Una seña también bloquea borrado');
set local "request.jwt.claim.sub"='00000000-0000-4000-8000-000000000902';
select public.complete_production('00000000-0000-4000-8000-000000000924',(public.production_order('00000000-0000-4000-8000-000000000924')->'items'->0->>'id')::uuid,'Listo');
select throws_ok($$select public.edit_order('00000000-0000-4000-8000-000000000922',3,(select jsonb_agg(jsonb_build_object('id',id,'description',description,'client_description',client_description,'specifications',specifications,'quantity',quantity,'amount',amount) order by position) from public.order_items where order_id='00000000-0000-4000-8000-000000000922'),'Trabajo editado','{}','Notas nuevas')$$,'42501',null,'Operario no modifica ítems');
select throws_ok($$select public.delete_order('00000000-0000-4000-8000-000000000922',3,1)$$,'42501',null,'Operario no borra notas');
set local "request.jwt.claim.sub"='00000000-0000-4000-8000-000000000901';
select throws_ok($$select public.edit_order('00000000-0000-4000-8000-000000000924',1,(select jsonb_agg(jsonb_build_object('id',id,'description',description,'client_description',client_description,'specifications',specifications,'quantity',quantity,'amount',amount) order by position) from public.order_items where order_id='00000000-0000-4000-8000-000000000924'),'Trabajo editado','{}','Notas nuevas')$$,'23514',null,'Un solo ítem terminado bloquea toda la nota');
select throws_ok($$select public.delete_order('00000000-0000-4000-8000-000000000924',1,(select number from public.orders where id='00000000-0000-4000-8000-000000000924'))$$,'23514',null,'No borra nota parcialmente terminada');
select throws_ok($$select public.save_order_work_details('00000000-0000-4000-8000-000000000924',1,(select jsonb_agg(jsonb_build_object('id',id,'description',description,'client_description',client_description,'specifications',specifications,'quantity',quantity,'amount',amount) order by position) from public.order_items where order_id='00000000-0000-4000-8000-000000000924'),'Cambio','{}')$$,'23514',null,'Tampoco permite editar ficha antigua de nota terminada');
select is((select count(*) from public.order_items where order_id='00000000-0000-4000-8000-000000000924' and production_status='completed'),1::bigint,'No pierde cierres');
-- Copia independiente y pases: el borrado es físico, sin borrar el cliente ni la copia.
select public.create_direct_order('00000000-0000-4000-8000-000000000929','00000000-0000-4000-8000-000000000921',null,null,'','[{"description":"Imanes","client_description":"Imanes de animales","specifications":"Cortar","quantity":100,"amount":"100"},{"description":"Folletos","client_description":"Folletos color","specifications":"","quantity":200,"amount":"200"}]',null,null,'00000000-0000-4000-8000-000000000922');
select lives_ok($$select public.delete_order('00000000-0000-4000-8000-000000000922',3,(select number from public.orders where id='00000000-0000-4000-8000-000000000922'))$$,'Borra nota editable con pases y copias');
select is((select count(*) from public.orders where id='00000000-0000-4000-8000-000000000922'),0::bigint,'Borrado físico de la nota');
select is((select count(*) from public.order_items where order_id='00000000-0000-4000-8000-000000000922'),0::bigint,'Borra sus ítems');
select is((select source_order_id from public.orders where id='00000000-0000-4000-8000-000000000929'),null::uuid,'Copia conserva datos sin referencia rota');
select is((select count(*) from public.orders where id='00000000-0000-4000-8000-000000000929'),1::bigint,'Copia sigue existiendo');
select is((select count(*) from public.customers where id='00000000-0000-4000-8000-000000000921'),1::bigint,'Cliente no se elimina');
select throws_ok($$select public.delete_order('00000000-0000-4000-8000-000000000922',3,1)$$,'P0002',null,'Repetir borrado no afecta otras notas');
select ok(not has_function_privilege('anon','public.edit_order(uuid,integer,jsonb,text,jsonb,text)','EXECUTE'),'Anónimo no edita');
select ok(not has_function_privilege('anon','public.delete_order(uuid,integer,bigint)','EXECUTE'),'Anónimo no borra');
select ok(not has_function_privilege('authenticated','private.lock_editable_order(uuid,integer)','EXECUTE'),'Helper inaccesible');
select public.save_quote('00000000-0000-4000-8000-000000000970',null,'Cliente edición','','','[{"description":"Imanes","quantity":1,"amount":"50"}]','00000000-0000-4000-8000-000000000921');
select public.approve_quote('00000000-0000-4000-8000-000000000970',1,'Aprobado');
select public.create_order_from_quote('00000000-0000-4000-8000-000000000970',2,'00000000-0000-4000-8000-000000000921',null,'00000000-0000-4000-8000-000000000971');
select lives_ok($$select public.delete_order(id,production_revision,number) from public.orders where quote_id='00000000-0000-4000-8000-000000000970'$$,'Borra nota creada desde presupuesto');
select is((select status from public.quotes where id='00000000-0000-4000-8000-000000000970'),'approved','Conserva presupuesto aprobado');
reset role;
select is((select count(*) from public.order_handoffs where order_id='00000000-0000-4000-8000-000000000922'),0::bigint,'No quedan pases huérfanos');
select * from finish();
rollback;
